function jCls(defCls) {
  var c = defCls || '';
  try {
    if (typeof MY_URL !== 'undefined' && MY_URL) {
      var pp = String(MY_URL).split('##');
      if (pp.length > 1 && pp[1]) c = pp[1];
    }
  } catch (e) {}
  return c;
