  if (!html) return out;
  var seen = {};
  var re = /href="\/video\/(\d+)\.html"/g, m;
  while ((m = re.exec(html))) {
    var id = m[1];
    if (!id || seen[id]) continue;
    seen[id] = 1;
    var block = html.slice(m.index, m.index + 4000);
    var pm = block.match(/<img[^>]+src="([^"]+)"/);
    var am = block.match(/alt="([^"]*)"/);
