  }
  var remark = dur || views;
  items.push({title: vtitle, img: poster, pic_url: poster, desc: (cat ? cat + ' | ' : '') + (year ? year + ' | ' : '') + remark, url: 'hiker://empty'});
  items.push({title: '剧情简介', col_type: 'text_1', url: 'hiker://empty'});
  items.push({title: synopsis, col_type: 'rich_text'});
  items.push({title: '播放线路：在线播放', col_type: 'text_1', url: 'hiker://empty'});
  var nid = '';
  var nm = durl.match(/\/video\/(\d+)\.html/);
  if (nm) nid = nm[1];
  var nodes = [['global', '全球加速节点'], ['asia', '亚洲加速节点'], ['china', '中国大陆加速节点']];
  var seenNode = {};
  var pm = html.match(/<a[^>]*href="\/play\/(\d+)\.html\?node=([a-z]+)"[^>]*>([\s\S]*?)<\/a>/g) || [];
  for (var p = 0; p < pm.length; p++) {
    var lm = pm[p].match(/\/play\/(\d+)\.html\?node=([a-z]+)"[^>]*>([\s\S]*?)<\/a>/);
    if (!lm || lm[1] !== nid || seenNode[lm[2]]) continue;
    seenNode[lm[2]] = 1;
    var label = jStrip(lm[3]).replace('▶', '').trim();
    if (!label) label = lm[2];
    var src = jExtractPlay(jGet(SITE + '/play/' + nid + '.html?node=' + lm[2]));
