  }
  var got = items.length;
  if (got <= 4) {
    for (var n = 0; n < nodes.length; n++) {
      if (seenNode[nodes[n][0]]) continue;
      var src2 = jExtractPlay(jGet(SITE + '/play/' + nid + '.html?node=' + nodes[n][0]));
